package core.advanced.window;

import java.util.HashMap;
import java.util.Map;

/**
 * @author maiqi
 * @title lcr014
 * @description TODO
 * @create 2023/9/19 17:15
 */
public class lcr014 {

    public static void main(String[] args) {
        lcr014 r = new lcr014();
        String s1 = "",
                s2 = "";

        System.out.println(r.checkInclusion(s1, s2));
    }

    public boolean checkInclusion(String s1, String s2) {
        Map<Character, Integer> bak = new HashMap<>(), win = new HashMap<>();
        for (char ch : s1.toCharArray()) {
            bak.compute(ch, (k, v) -> v == null ? 1 : v + 1);
        }

        bak.forEach((k, v) -> System.out.printf("%c // %d\n", k, v.intValue()));

        int m = s1.length(), n = s2.length(), match = 0, len, target = bak.keySet().size();
        char ch;

        for (int i = 0, j = 0; j < n; ) { // 右指针遍历
            if (!bak.containsKey(ch = s2.charAt(j))) {
                win.clear();
                match = 0;
                i = ++j;
                continue;
            }

            // win=[i, j) j
            // ch[j] 加不进来的两种情况，一种 ch[j]满了，另一种windows空间满了
            while ((len = j - i) == m || bak.get(ch = s2.charAt(j)).equals(win.getOrDefault(ch, 0))) {
                if (win.getOrDefault(ch, 0).equals(bak.get(ch))) {
                    match--;
                }
                win.compute(ch = s2.charAt(i), (k, v) -> v - 1);
                i++;
            }

            // 加进来
            win.compute(ch, (k, v) -> v == null ? 1 : v + 1);
            if (win.get(ch).equals(bak.get(ch))) {
                match++;
            }
            j++;

            if (match == target) return true;
        }

        return false;
    }
}
